74	//手势事件处理函数
75	static void gesture_event_handler(lv_event_t *e)
76	{
77	    lv_event_code_t code = lv_event_get_code(e);
78	    lv_obj_t *obj = lv_event_get_target(e);
79	    lv_indev_t *indev = lv_event_get_indev(e);
80	    
81	    if (!indev) return;
82	    
83	    lv_point_t point;
84	    lv_indev_get_point(indev, &point);
85	    
86	    switch (code) {
87	        case LV_EVENT_PRESSED:
88	            gesture_start_x = point.x;
89	            gesture_start_y = point.y;
90	            gesture_in_progress = true;
91	            break;
92	        case LV_EVENT_RELEASED:
93	            if (gesture_in_progress) {
94	                int delta_x = point.x - gesture_start_x;
95	                int delta_y = point.y - gesture_start_y;
96	                
97	                // 检查是否是右滑手势（水平滑动距离大于阈值，且垂直滑动较小）
98	                if (delta_x > gesture_threshold && abs(delta_y) < gesture_threshold) {
99	                    hide_page();
100	                }
101	                
102	                gesture_in_progress = false;
103	            }
104	            break;
105	        default:
106	            break;
107	    }
108	}
