110	/* Send a JSON text frame built with cJSON. */
111	static int send_json(struct xiaozhi_app_s *app, cJSON *root)
112	{
113	  char *json = cJSON_PrintUnformatted(root);
114	  if (json == NULL)
115	    {
116	      return -ENOMEM;
117	    }
118	
119	  int ret = xiaozhi_ws_send_text(&app->ws, json, strlen(json));
120	  free(json);
121	  return ret;
122	}
123	
124	/* Uplink worker: capture Opus frames and send as binary frames for the
125	 * given number of seconds.
126	 */
127	static void *uplink_worker(void *arg)
128	{
129	  struct uplink_ctx_s *uc = arg;
130	  struct xiaozhi_app_s *app = uc->app;
131	  uint8_t frame[XZ_OPUS_MAX];
132	  int frames = 0;
133	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
134	
135	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
136	         target_frames, uc->seconds);
137	
138	  while (frames < target_frames && app->ws_connected)
139	    {
140	      ssize_t n = xiaozhi_audio_read_opus(&app->audio, frame, sizeof(frame));
141	      if (n < 0)
142	        {
143	          printf("[xiaozhi] uplink read err: %zd\n", n);
144	          break;
145	        }
146	
147	      if (n > 0)
148	        {
149	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
150	          if (ret != 0)
151	            {
152	              printf("[xiaozhi] uplink send err: %d\n", ret);
153	              break;
154	            }
155	
156	          frames++;
157	        }
158	    }
159	
160	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
161	  return NULL;
162	}
