164	/* Receive worker: parse server messages and feed TTS audio to the player.
165	 * Runs until ws is closed or a stop condition.
166	 */
167	static void recv_loop(struct xiaozhi_app_s *app, int max_ms,
168	                      bool stop_on_hello)
169	{
170	  int waited = 0;
171	
172	  while (app->ws_connected && waited < max_ms)
173	    {
174	      const uint8_t *payload;
175	      size_t plen;
176	      bool is_binary;
177	      int ret;
178	
179	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
180	      if (ret != 0)
181	        {
182	          app->ws_connected = false;
183	          break;
184	        }
185	
186	      if (is_binary)
187	        {
188	          /* Server TTS Opus frame -> feed to player. */
189	          if (app->tts_playing)
190	            {
191	              xiaozhi_audio_write_opus(&app->audio, payload, plen);
192	            }
193	
194	          waited += 60;
195	          continue;
196	        }
197	
198	      /* Text frame: parse JSON. */
199	      {
200	        char *json = malloc(plen + 1);
201	        if (json == NULL)
202	          {
203	            continue;
204	          }
205	
206	        memcpy(json, payload, plen);
207	        json[plen] = '\0';
208	
209	        cJSON *root = cJSON_Parse(json);
210	        if (root != NULL)
211	          {
212	            cJSON *type = cJSON_GetObjectItem(root, "type");
213	            const char *tstr = cJSON_IsString(type) ?
214	              type->valuestring : "";
215	
216	            if (strcmp(tstr, "stt") == 0)
217	              {
218	                cJSON *text = cJSON_GetObjectItem(root, "text");
219	                const char *s = text ? text->valuestring : "?";
220	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
221	                app->got_stt = true;
222	                strncpy(app->stt_text, s, sizeof(app->stt_text) - 1);
223	                app->stt_text[sizeof(app->stt_text) - 1] = '\0';
224	              }
225	            else if (strcmp(tstr, "llm") == 0)
226	              {
227	                cJSON *text = cJSON_GetObjectItem(root, "text");
228	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
229	                       text ? text->valuestring : "?");
230	              }
231	            else if (strcmp(tstr, "tts") == 0)
232	              {
233	                cJSON *state = cJSON_GetObjectItem(root, "state");
234	                const char *sstr = cJSON_IsString(state) ?
235	                  state->valuestring : "";
236	
237	                if (strcmp(sstr, "start") == 0)
238	                  {
239	                    app->tts_playing = true;
240	                    app->state = XZ_STATE_PLAYING;
241	                    xiaozhi_audio_start_playback(&app->audio);
242	                    printf("[xiaozhi] <<< TTS start\n");
243	                  }
244	                else if (strcmp(sstr, "stop") == 0)
245	                  {
246	                    app->tts_playing = false;
247	                    printf("[xiaozhi] <<< TTS stop\n");
248	                    xiaozhi_audio_stop_playback(&app->audio);
249	                    cJSON_Delete(root);
250	                    free(json);
251	                    break;   /* end of this turn */
252	                  }
253	                else if (strcmp(sstr, "sentence_start") == 0)
254	                  {
255	                    cJSON *text = cJSON_GetObjectItem(root, "text");
256	                    const char *s = text ? text->valuestring : "?";
257	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
258	                    app->tts_sentences++;
259	                    strncpy(app->tts_text, s, sizeof(app->tts_text) - 1);
260	                    app->tts_text[sizeof(app->tts_text) - 1] = '\0';
261	                  }
262	              }
263	            else if (strcmp(tstr, "goodbye") == 0)
264	              {
265	                printf("[xiaozhi] <<< goodbye\n");
266	                app->ws_connected = false;
267	                cJSON_Delete(root);
268	                free(json);
269	                break;
270	              }
271	            else if (strcmp(tstr, "hello") == 0)
272	              {
273	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
274	                if (cJSON_IsString(sid))
275	                  {
276	                    strncpy(app->session_id, sid->valuestring,
277	                            sizeof(app->session_id) - 1);
278	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
279	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
280	                           app->session_id);
281	                  }
282	
283	                /* In the connect phase we only need the hello response to
284	                 * obtain the session_id; bail out so we don't block here
285	                 * waiting for server audio that never comes before we've
286	                 * sent listen:start. The server also times out (~10s) if
287	                 * it doesn't see a listen request soon after hello.
288	                 */
289	                if (stop_on_hello)
290	                  {
291	                    cJSON_Delete(root);
292	                    free(json);
293	                    return;
294	                  }
295	              }
296	            else
297	              {
298	                printf("[xiaozhi] <<< %s\n", tstr);
299	              }
300	
301	            cJSON_Delete(root);
302	          }
303	        else
304	          {
305	            printf("[xiaozhi] <<< (parse err) %.*s\n",
306	                   (int)plen, (const char *)payload);
307	          }
308	
309	        free(json);
310	      }
311	
312	      waited += 60;
313	    }
314	}
