316	/* Dialog thread: runs the full OTA -> dialog flow off the main (UI) thread.
317	 */
318	static void *dialog_thread(void *arg)
319	{
320	  struct xiaozhi_app_s *app = arg;
321	  struct xiaozhi_ota_config_s ota;
322	  const char *mac = XIAOZHI_MAC_DEFAULT;
323	  char client_id[40];
324	  int ret;
325	
326	  snprintf(client_id, sizeof(client_id),
327	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
328	
329	  /* Init audio subsystem. */
330	  ret = xiaozhi_audio_init(&app->audio);
331	  if (ret != 0)
332	    {
333	      printf("[xiaozhi] audio init failed: %d\n", ret);
334	      app->state = XZ_STATE_ERROR;
335	      return NULL;
336	    }
337	
338	  /* Step 1: OTA. */
339	  app->state = XZ_STATE_OTA;
340	  printf("[xiaozhi] step 1: OTA\n");
341	  ret = xiaozhi_ota_fetch(mac, &ota);
342	  if (ret != 0)
343	    {
344	      printf("[xiaozhi] OTA failed: %d\n", ret);
345	      app->state = XZ_STATE_ERROR;
346	      return NULL;
347	    }
348	
349	  /* Step 2: wss connect (TLS + ws upgrade). */
350	  app->state = XZ_STATE_CONNECT;
351	  printf("[xiaozhi] step 2: wss connect\n");
352	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
353	                           client_id);
354	  if (ret != 0)
355	    {
356	      printf("[xiaozhi] ws connect failed: %d\n", ret);
357	      app->state = XZ_STATE_ERROR;
358	      return NULL;
359	    }
360	
361	  app->ws_connected = true;
362	
363	  /* Step 3: send the hello handshake, then wait for the server's hello
364	   * response which carries the session_id. The server times out (~10s)
365	   * if it never receives a hello, so we must send ours first.
366	   */
367	  printf("[xiaozhi] step 3: send hello + wait hello response\n");
368	  {
369	    cJSON *hello = cJSON_CreateObject();
370	    cJSON_AddStringToObject(hello, "type", "hello");
371	    cJSON_AddNumberToObject(hello, "version", 3);
372	    cJSON_AddStringToObject(hello, "transport", "websocket");
373	
374	    cJSON *ap = cJSON_CreateObject();
375	    cJSON_AddStringToObject(ap, "format", "opus");
376	    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
377	    cJSON_AddNumberToObject(ap, "channels", 1);
378	    cJSON_AddNumberToObject(ap, "frame_duration", 60);
379	    cJSON_AddItemToObject(hello, "audio_params", ap);
380	
381	    ret = send_json(app, hello);
382	    cJSON_Delete(hello);
383	    if (ret != 0)
384	      {
385	        printf("[xiaozhi] hello send failed: %d\n", ret);
386	        app->state = XZ_STATE_ERROR;
387	        goto out;
388	      }
389	    printf("[xiaozhi] >>> hello (v3, websocket, opus/16k/60ms)\n");
390	  }
391	
392	  /* Receive the server hello response to get session_id. stop_on_hello
393	   * returns immediately once we have it, so we don't block waiting for
394	   * audio the server won't send before listen:start.
395	   */
396	  recv_loop(app, 5000, true);
397	  if (app->session_id[0] == '\0')
398	    {
399	      printf("[xiaozhi] no session_id, abort\n");
400	      app->state = XZ_STATE_ERROR;
401	      goto out;
402	    }
403	
404	  /* Step 4: listen start + capture + listen stop. */
405	  app->state = XZ_STATE_LISTENING;
406	  printf("[xiaozhi] step 4: listen start + capture\n");
407	  {
408	    cJSON *listen = cJSON_CreateObject();
409	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
410	    cJSON_AddStringToObject(listen, "type", "listen");
411	    cJSON_AddStringToObject(listen, "state", "start");
412	    cJSON_AddStringToObject(listen, "mode", "manual");
413	    send_json(app, listen);
414	    cJSON_Delete(listen);
415	    printf("[xiaozhi] >>> listen start\n");
416	  }
417	
418	  ret = xiaozhi_audio_start_capture(&app->audio);
419	  if (ret != 0)
420	    {
421	      printf("[xiaozhi] capture start failed: %d\n", ret);
422	      app->state = XZ_STATE_ERROR;
423	      goto out;
424	    }
425	
426	  {
427	    struct uplink_ctx_s uc;
428	    uc.app = app;
429	    uc.seconds = XZ_DIALOG_SECONDS;
430	    uplink_worker(&uc);
431	  }
432	
433	  xiaozhi_audio_stop_capture(&app->audio);
434	
435	  /* listen stop. */
436	  {
437	    cJSON *stop = cJSON_CreateObject();
438	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
439	    cJSON_AddStringToObject(stop, "type", "listen");
440	    cJSON_AddStringToObject(stop, "state", "stop");
441	    send_json(app, stop);
442	    cJSON_Delete(stop);
443	    printf("[xiaozhi] >>> listen stop\n");
444	  }
445	
446	  /* Step 5: receive stt + tts + playback (up to 20s). */
447	  app->state = XZ_STATE_THINKING;
448	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
449	  recv_loop(app, 20000, false);
450	
451	out:
452	  if (app->tts_playing)
453	    {
454	      xiaozhi_audio_stop_playback(&app->audio);
455	    }
456	
457	  xiaozhi_audio_deinit(&app->audio);
458	  xiaozhi_ws_close(&app->ws);
459	
460	  app->state = app->ws_connected ? XZ_STATE_DONE : XZ_STATE_DONE;
461	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
462	         app->got_stt ? "yes" : "no", app->tts_sentences);
463	  return NULL;
464	}
