466	/* Start button click handler: kicks off the dialog thread on demand.
467	 * The user taps this after WiFi is up, so OTA can reach the server.
468	 */
469	static void start_btn_event_cb(lv_event_t *e)
470	{
471	  struct xiaozhi_app_s *app = &g_app;
472	  LV_UNUSED(e);
473	
474	  if (app->dialog_started)
475	    {
476	      return;   /* already running */
477	    }
478	
479	  app->dialog_started = true;
480	  app->state = XZ_STATE_OTA;
481	
482	  /* Hide the start button once the dialog is launched. */
483	  if (app->start_btn != NULL)
484	    {
485	      lv_obj_add_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
486	    }
487	
488	  pthread_attr_t attr;
489	  pthread_attr_init(&attr);
490	  pthread_attr_setstacksize(&attr, 16384);
491	
492	  int ret = pthread_create(NULL, &attr, dialog_thread, app);
493	  pthread_attr_destroy(&attr);
494	
495	  if (ret != 0)
496	    {
497	      printf("[xiaozhi] dialog thread create failed: %d\n", ret);
498	      app->state = XZ_STATE_ERROR;
499	    }
500	}
