#ifndef XIAOZHI_MCP_H
#define XIAOZHI_MCP_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/****************************************************************************
 * MCP Tool Call Handler
 *
 * Protocol:
 *   Server -> Device: {"type":"tool_call","id":"xxx","name":"set_timer","arguments":{...}}
 *   Device -> Server: {"type":"tool_result","id":"xxx","result":{...}}
 *
 * The device parses tool_call, executes the local function, and sends
 * tool_result back via WebSocket.
 ****************************************************************************/

/* Maximum number of registered tools. */
#define MCP_MAX_TOOLS 16

/* Maximum length of tool name. */
#define MCP_TOOL_NAME_MAX 32

/* Maximum length of tool result JSON. */
#define MCP_RESULT_MAX 256

/* Tool handler callback.
 * args: JSON string of the "arguments" object from the tool_call.
 * result: buffer to write the result JSON string.
 * result_max: size of the result buffer.
 * Returns 0 on success, negative on error.
 */
typedef int (*mcp_tool_handler_t)(const char *args,
                                  char *result, int result_max);

/* Tool registration entry. */
struct mcp_tool_entry {
    char name[MCP_TOOL_NAME_MAX];
    mcp_tool_handler_t handler;
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/* Initialize the MCP tool registry. Call once at startup. */
void mcp_init(void);

/* Register a tool. Returns 0 on success, -1 if registry is full. */
int mcp_register_tool(const char *name, mcp_tool_handler_t handler);

/* Handle a tool_call message from the server.
 * call_id: the "id" field from the tool_call message.
 * name: the "name" field (tool name).
 * args_json: the "arguments" object as a JSON string (may be "{}").
 * Returns a JSON string that should be sent back as tool_result.
 * The returned string is valid until the next mcp_handle_tool_call.
 */
const char *mcp_handle_tool_call(const char *call_id,
                                 const char *name,
                                 const char *args_json);

/* ---- Built-in tool handlers ---- */

/* Timer tools: "set_timer", "cancel_timer" */
int mcp_tool_set_timer(const char *args, char *result, int result_max);
int mcp_tool_cancel_timer(const char *args, char *result, int result_max);

#ifdef __cplusplus
}
#endif

#endif /* XIAOZHI_MCP_H */

