/****************************************************************************
 * xiaozhi_mcp.c
 *
 * MCP (Model Context Protocol) tool call handler for xiaozhi_voice.
 *
 * Handles tool_call messages from the server, dispatches to local
 * handlers, and returns tool_result JSON.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#include <netutils/cJSON.h>

#include "xiaozhi_mcp.h"

/* Timer control functions (defined in timer_main.c). */
extern void run_create_timer(int32_t ms);
extern void run_reset(void);
extern bool timer_is_running(void);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct mcp_tool_entry g_tools[MCP_MAX_TOOLS];
static int g_tool_count = 0;

/* Scratch buffer for building tool_result JSON. */
static char g_result_buf[MCP_RESULT_MAX];

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void mcp_init(void)
{
  g_tool_count = 0;
  memset(g_tools, 0, sizeof(g_tools));

  /* Register built-in tools. */
  mcp_register_tool("set_timer", mcp_tool_set_timer);
  mcp_register_tool("cancel_timer", mcp_tool_cancel_timer);

  printf("[xiaozhi] MCP: registered %d tools\n", g_tool_count);
}

int mcp_register_tool(const char *name, mcp_tool_handler_t handler)
{
  if (g_tool_count >= MCP_MAX_TOOLS || name == NULL || handler == NULL)
    {
      return -1;
    }

  struct mcp_tool_entry *e = &g_tools[g_tool_count];
  strncpy(e->name, name, MCP_TOOL_NAME_MAX - 1);
  e->name[MCP_TOOL_NAME_MAX - 1] = '\0';
  e->handler = handler;
  g_tool_count++;

  printf("[xiaozhi] MCP: registered tool \"%s\"\n", name);
  return 0;
}

const char *mcp_handle_tool_call(const char *call_id,
                                 const char *name,
                                 const char *args_json)
{
  printf("[xiaozhi] MCP: tool_call id=%s name=%s args=%s\n",
         call_id ? call_id : "null",
         name ? name : "null",
         args_json ? args_json : "{}");

  /* Find the tool handler. */
  mcp_tool_handler_t handler = NULL;
  for (int i = 0; i < g_tool_count; i++)
    {
      if (strcmp(g_tools[i].name, name) == 0)
        {
          handler = g_tools[i].handler;
          break;
        }
    }

  if (handler == NULL)
    {
      printf("[xiaozhi] MCP: unknown tool \"%s\"\n", name);
      snprintf(g_result_buf, MCP_RESULT_MAX,
               "{\"success\":false,\"error\":\"unknown tool: %s\"}",
               name ? name : "null");
      return g_result_buf;
    }

  /* Execute the tool handler. */
  int ret = handler(args_json ? args_json : "{}",
                    g_result_buf, MCP_RESULT_MAX);
  if (ret != 0)
    {
      printf("[xiaozhi] MCP: tool \"%s\" failed: %d\n", name, ret);
      snprintf(g_result_buf, MCP_RESULT_MAX,
               "{\"success\":false,\"error\":\"tool execution failed\"}");
    }

  printf("[xiaozhi] MCP: tool \"%s\" result: %s\n", name, g_result_buf);
  return g_result_buf;
}

/****************************************************************************
 * Built-in Tool Handlers
 ****************************************************************************/

/* set_timer: {"minutes": 5, "seconds": 30} or {"minutes": 10} */
int mcp_tool_set_timer(const char *args, char *result, int result_max)
{
  cJSON *root = cJSON_Parse(args);
  if (root == NULL)
    {
      snprintf(result, result_max,
               "{\"success\":false,\"error\":\"invalid JSON args\"}");
      return -1;
    }

  cJSON *j_minutes = cJSON_GetObjectItem(root, "minutes");
  cJSON *j_seconds = cJSON_GetObjectItem(root, "seconds");

  int minutes = cJSON_IsNumber(j_minutes) ? j_minutes->valueint : 0;
  int seconds = cJSON_IsNumber(j_seconds) ? j_seconds->valueint : 0;
  cJSON_Delete(root);

  int total_ms = (minutes * 60 + seconds) * 1000;
  if (total_ms <= 0)
    {
      snprintf(result, result_max,
               "{\"success\":false,\"error\":\"invalid time: %dm %ds\"}",
               minutes, seconds);
      return -1;
    }

  printf("[xiaozhi] MCP: set_timer %dm %ds (%dms)\n",
         minutes, seconds, total_ms);

  /* Call the timer module to create and start the timer. */
  run_create_timer(total_ms);

  snprintf(result, result_max,
           "{\"success\":true,\"message\":\"Timer set for %d minutes %d seconds\"}",
           minutes, seconds);
  return 0;
}

/* cancel_timer: no arguments needed */
int mcp_tool_cancel_timer(const char *args, char *result, int result_max)
{
  LV_UNUSED(args);

  printf("[xiaozhi] MCP: cancel_timer\n");

  /* Call the timer module to reset/cancel. */
  run_reset();

  snprintf(result, result_max,
           "{\"success\":true,\"message\":\"Timer cancelled\"}");
  return 0;
}

