176	
177	          s += 3;
178	        }
179	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
180	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
181	        {
182	          s += 2;
183	        }
