232	    {
233	      printf("[xiaozhi] in while show, frames=%d, target=%d, connected=%d\n",
234	             frames, target_frames, app->ws_connected);
235	      ssize_t n = xiaozhi_audio_read_opus(app->audio, frame, sizeof(frame));
236	      printf("[xiaozhi] read_opus returned: %zd\n", n);
237	      if (n < 0)
238	        {
239	          printf("[xiaozhi] uplink read err: %zd\n", n);
240	          break;
241	        }
242	
243	      if (n > 0)
244	        {
245	          /* Debug: hex dump first Opus frames for format verification. */
246	          if (frames < 3)
247	            {
248	              printf("[xiaozhi] opus frame[%d] len=%zd\n", frames, n);
249	              for (ssize_t i = 0; i < n && i < 32; i++)
250	                {
251	                  printf("%02x ", frame[i]);
252	                }
253	              printf("\n");
254	            }
255	
256	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
257	          if (ret != 0)
258	            {
259	              printf("[xiaozhi] uplink send err: %d\n", ret);
260	              break;
261	            }
262	
263	          frames++;
264	        }
265	    }
266	
267	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
268	  return NULL;
269	}
270	
271	/* Receive worker: parse server messages and feed TTS audio to the player.
272	 * Runs until ws is closed or a stop condition.
273	 */
274	static void recv_loop(struct xiaozhi_app_s *app, int max_ms,
275	                      bool stop_on_hello)
276	{
277	  int waited = 0;
278	
279	  while (app->ws_connected && waited < max_ms)
280	    {
281	      const uint8_t *payload;
282	      size_t plen;
283	      bool is_binary;
284	      int ret;
285	
286	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
287	      if (ret != 0)
288	        {
289	          app->ws_connected = false;
290	          break;
291	        }
292	
293	      if (is_binary)
294	        {
295	          printf("[xiaozhi] <<< binary frame: %zu bytes\n", plen);
296	          /* Server TTS Opus frame -> feed to player. */
297	          if (app->tts_playing)
298	            {
299	              xiaozhi_audio_write_opus(app->audio, payload, plen);
300	            }
301	
302	          waited += 60;
303	          continue;
304	        }
305	
306	      /* Text frame: parse JSON. */
307	      {
308	        char *json = malloc(plen + 1);
309	        if (json == NULL)
310	          {
311	            continue;
312	          }
313	
314	        memcpy(json, payload, plen);
315	        json[plen] = '\0';
316	
317	        cJSON *root = cJSON_Parse(json);
318	        if (root != NULL)
319	          {
320	            /* Print all received text messages for debugging. */
321	            printf("[xiaozhi] <<< recv: %s\n", json);
322	
323	            cJSON *type = cJSON_GetObjectItem(root, "type");
324	            const char *tstr = cJSON_IsString(type) ?
325	              type->valuestring : "";
326	
327	            if (strcmp(tstr, "stt") == 0)
328	              {
329	                cJSON *text = cJSON_GetObjectItem(root, "text");
330	                const char *s = text ? text->valuestring : "?";
331	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
332	                app->got_stt = true;
333	                sanitize_text(app->stt_text, sizeof(app->stt_text), s);
334	              }
335	            else if (strcmp(tstr, "llm") == 0)
336	              {
337	                cJSON *text = cJSON_GetObjectItem(root, "text");
338	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
339	                       text ? text->valuestring : "?");
340	              }
341	            else if (strcmp(tstr, "tts") == 0)
342	              {
343	                cJSON *state = cJSON_GetObjectItem(root, "state");
344	                const char *sstr = cJSON_IsString(state) ?
345	                  state->valuestring : "";
346	
347	                if (strcmp(sstr, "start") == 0)
348	                  {
349	                    app->tts_playing = true;
350	                    app->state = XZ_STATE_PLAYING;
351	                    xiaozhi_audio_start_playback(app->audio);
352	                    printf("[xiaozhi] <<< TTS start\n");
353	                  }
354	                else if (strcmp(sstr, "stop") == 0)
355	                  {
356	                    app->tts_playing = false;
357	                    printf("[xiaozhi] <<< TTS stop\n");
358	                    xiaozhi_audio_stop_playback(app->audio);
359	                    cJSON_Delete(root);
360	                    free(json);
361	                    break;   /* end of this turn */
362	                  }
363	                else if (strcmp(sstr, "sentence_start") == 0)
364	                  {
365	                    cJSON *text = cJSON_GetObjectItem(root, "text");
366	                    const char *s = text ? text->valuestring : "?";
367	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
368	                    app->tts_sentences++;
369	                    sanitize_text(app->tts_text, sizeof(app->tts_text), s);
370	                  }
371	              }
372	            else if (strcmp(tstr, "goodbye") == 0)
373	              {
374	                printf("[xiaozhi] <<< goodbye\n");
375	                app->ws_connected = false;
376	                cJSON_Delete(root);
377	                free(json);
378	                break;
379	              }
380	            else if (strcmp(tstr, "hello") == 0)
381	              {
382	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
383	                if (cJSON_IsString(sid))
384	                  {
385	                    strncpy(app->session_id, sid->valuestring,
386	                            sizeof(app->session_id) - 1);
387	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
388	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
389	                           app->session_id);
390	                  }
391	
392	                /* In the connect phase we only need the hello response to
393	                 * obtain the session_id; bail out so we don't block here
394	                 * waiting for server audio that never comes before we've
395	                 * sent listen:start. The server also times out (~10s) if
396	                 * it doesn't see a listen request soon after hello.
397	                 */
398	                if (stop_on_hello)
399	                  {
400	                    cJSON_Delete(root);
401	                    free(json);
402	                    return;
403	                  }
404	              }
405	            else
406	              {
407	                /* Print full message for debugging unknown types (e.g. error). */
408	                char *out = cJSON_PrintUnformatted(root);
409	                printf("[xiaozhi] <<< %s\n", out ? out : tstr);
410	                if (out)
411	                  {
412	                    free(out);
413	                  }
414	              }
415	
416	            cJSON_Delete(root);
417	          }
418	        else
419	          {
420	            printf("[xiaozhi] <<< (parse err) %.*s\n",
421	                   (int)plen, (const char *)payload);
422	          }
423	
424	        free(json);
425	      }
426	
427	      waited += 60;
428	    }
429	}
430	
431	/* Dialog thread: runs the full OTA -> dialog flow off the main (UI) thread.
432	 */
433	static void *dialog_thread(void *arg)
434	{
435	  struct xiaozhi_app_s *app = arg;
436	  struct xiaozhi_ota_config_s ota;
437	  const char *mac = XIAOZHI_MAC_DEFAULT;
438	  char client_id[40];
439	  int ret;
440	
441	  snprintf(client_id, sizeof(client_id),
442	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
443	
444	  /* Init audio subsystem (creates Opus encoder). */
445	  app->audio = xiaozhi_audio_init();
446	  if (app->audio == NULL)
447	    {
448	      printf("[xiaozhi] audio init failed\n");
449	      app->state = XZ_STATE_ERROR;
450	      return NULL;
451	    }
452	
453	  /* Step 1: OTA. */
454	  app->state = XZ_STATE_OTA;
455	  printf("[xiaozhi] step 1: OTA\n");
456	  ret = xiaozhi_ota_fetch(mac, &ota);
457	  if (ret != 0)
458	    {
459	      printf("[xiaozhi] OTA failed: %d\n", ret);
460	      app->state = XZ_STATE_ERROR;
461	      return NULL;
462	    }
463	
464	  /* Step 2: wss connect (TLS + ws upgrade). */
465	  app->state = XZ_STATE_CONNECT;
466	  printf("[xiaozhi] step 2: wss connect\n");
467	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
468	                           client_id);
469	  if (ret != 0)
470	    {
471	      printf("[xiaozhi] ws connect failed: %d\n", ret);
472	      app->state = XZ_STATE_ERROR;
473	      return NULL;
474	    }
475	
476	  app->ws_connected = true;
477	
478	  /* Step 3: send the hello handshake, then wait for the server's hello
479	   * response which carries the session_id. The server times out (~10s)
480	   * if it never receives a hello, so we must send ours first.
481	   */
482	  printf("[xiaozhi] step 3: send hello + wait hello response\n");
483	  {
484	    cJSON *hello = cJSON_CreateObject();
485	    cJSON_AddStringToObject(hello, "type", "hello");
486	    cJSON_AddNumberToObject(hello, "version", 3);
487	    cJSON_AddStringToObject(hello, "transport", "websocket");
488	
489	    cJSON *ap = cJSON_CreateObject();
490	    cJSON_AddStringToObject(ap, "format", "opus");
491	    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
492	    cJSON_AddNumberToObject(ap, "channels", 1);
493	    cJSON_AddNumberToObject(ap, "frame_duration", 60);
494	    cJSON_AddItemToObject(hello, "audio_params", ap);
495	
496	    char *hello_str = cJSON_PrintUnformatted(hello);
497	    printf("[xiaozhi] >>> hello json: %s\n", hello_str ? hello_str : "null");
498	    if (hello_str)
499	      {
500	        free(hello_str);
501	      }
502	    ret = send_json(app, hello);
503	    cJSON_Delete(hello);
504	    if (ret != 0)
505	      {
506	        printf("[xiaozhi] hello send failed: %d\n", ret);
507	        app->state = XZ_STATE_ERROR;
508	        goto out;
509	      }
510	  }
511	
512	  /* Receive the server hello response to get session_id. stop_on_hello
513	   * returns immediately once we have it, so we don't block waiting for
514	   * audio the server won't send before listen:start.
515	   */
516	  recv_loop(app, 5000, true);
517	  if (app->session_id[0] == '\0')
518	    {
519	      printf("[xiaozhi] no session_id, abort\n");
520	      app->state = XZ_STATE_ERROR;
521	      goto out;
522	    }
523	
524	  /* Step 4: listen start + capture + listen stop. */
525	  app->state = XZ_STATE_LISTENING;
526	  printf("[xiaozhi] step 4: listen start + capture, session_id=%s\n",
527	         app->session_id);
528	  {
529	    cJSON *listen = cJSON_CreateObject();
530	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
531	    cJSON_AddStringToObject(listen, "type", "listen");
532	    cJSON_AddStringToObject(listen, "state", "start");
533	    cJSON_AddStringToObject(listen, "mode", "manual");
534	    char *json_str = cJSON_PrintUnformatted(listen);
535	    printf("[xiaozhi] >>> listen start json: %s\n", json_str ? json_str : "null");
536	    if (json_str)
537	      {
538	        free(json_str);
539	      }
540	    send_json(app, listen);
541	    cJSON_Delete(listen);
542	  }
543	
544	  ret = xiaozhi_audio_start_capture(app->audio);
545	  if (ret != 0)
546	    {
547	      printf("[xiaozhi] capture start failed: %d\n", ret);
548	      app->state = XZ_STATE_ERROR;
549	      goto out;
550	    }
551	
552	  {
553	    struct uplink_ctx_s uc;
554	    uc.app = app;
555	    uc.seconds = XZ_DIALOG_SECONDS;
556	    uplink_worker(&uc);
557	  }
558	
559	  xiaozhi_audio_stop_capture(app->audio);
560	
561	  /* listen stop. */
562	  {
563	    cJSON *stop = cJSON_CreateObject();
564	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
565	    cJSON_AddStringToObject(stop, "type", "listen");
566	    cJSON_AddStringToObject(stop, "state", "stop");
567	    char *json_str = cJSON_PrintUnformatted(stop);
568	    printf("[xiaozhi] >>> listen stop json: %s\n", json_str ? json_str : "null");
569	    if (json_str)
570	      {
571	        free(json_str);
572	      }
573	    send_json(app, stop);
574	    cJSON_Delete(stop);
575	  }
576	
577	  /* Step 5: receive stt + tts + playback (up to 20s). */
578	  app->state = XZ_STATE_THINKING;
579	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
580	  recv_loop(app, 20000, false);
581	
582	out:
583	  if (app->tts_playing)
584	    {
585	      xiaozhi_audio_stop_playback(app->audio);
586	    }
587	
588	  xiaozhi_audio_deinit(app->audio);
589	  xiaozhi_ws_close(&app->ws);
590	
591	  app->state = XZ_STATE_DONE;
592	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
593	         app->got_stt ? "yes" : "no", app->tts_sentences);
594	
595	  /* Reset state so user can start a new conversation. */
596	  app->dialog_started = false;
597	  app->ws_connected = false;
598	  app->got_stt = false;
599	  app->tts_playing = false;
600	  app->tts_sentences = 0;
601	  memset(app->session_id, 0, sizeof(app->session_id));
602	  memset(app->stt_text, 0, sizeof(app->stt_text));
603	  memset(app->tts_text, 0, sizeof(app->tts_text));
604	
605	  /* Show the start button for the next conversation. */
606	  if (app->start_btn != NULL)
607	    {
608	      lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
609	    }
610	
611	  return NULL;
612	}
613	
614	/* Start button click handler: kicks off the dialog thread on demand.
615	 * The user taps this after WiFi is up, so OTA can reach the server.
616	 */
617	static void start_btn_event_cb(lv_event_t *e)
618	{
619	  struct xiaozhi_app_s *app = &g_app;
620	  LV_UNUSED(e);
621	
622	  if (app->dialog_started)
623	    {
624	      return;   /* already running */
625	    }
626	
627	  app->dialog_started = true;
628	  app->state = XZ_STATE_OTA;
629	
630	  /* Hide the start button once the dialog is launched. */
631	  if (app->start_btn != NULL)
632	    {
633	      lv_obj_add_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
634	    }
635	
636	  pthread_attr_t attr;
637	  pthread_attr_init(&attr);
638	  pthread_attr_setstacksize(&attr, 65536);
639	
640	  int ret = pthread_create(NULL, &attr, dialog_thread, app);
641	  pthread_attr_destroy(&attr);
642	
643	  if (ret != 0)
644	    {
645	      printf("[xiaozhi] dialog thread create failed: %d\n", ret);
646	      app->state = XZ_STATE_ERROR;
647	      app->dialog_started = false;
648	      if (app->start_btn != NULL)
649	        {
650	          lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
651	        }
652	    }
653	}
