655	/* Build the LVGL main screen. */
656	static void ui_create(struct xiaozhi_app_s *app)
657	{
658	  lv_obj_t *scr = get_watch_scr();
659	  lv_obj_set_style_bg_color(scr, lv_color_white(), 0);
660	
661	  /* Use the default font for English UI elements. */
662	  const lv_font_t *font = lv_font_default();
663	
664	  /* Use Chinese-capable font for STT/TTS text display. */
665	  const lv_font_t *cjk_font = font_manager_get_font(FONT_SMALL);
666	
667	  /* Title. */
668	  lv_obj_t *title = lv_label_create(scr);
669	  lv_label_set_text(title, "Xiaozhi Voice");
670	  lv_obj_set_style_text_font(title, font, 0);
671	  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 20);
672	
673	  /* Status line. */
674	  app->status_label = lv_label_create(scr);
675	  lv_label_set_text(app->status_label, g_state_names[app->state]);
676	  lv_obj_set_style_text_font(app->status_label, font, 0);
677	  lv_obj_set_style_text_color(app->status_label, lv_color_hex(0x1e88e5), 0);
678	  lv_obj_align(app->status_label, LV_ALIGN_TOP_MID, 0, 60);
679	
680	  /* Start button: user taps this (after WiFi is up) to begin the dialog. */
681	  app->start_btn = lv_button_create(scr);
682	  lv_obj_set_size(app->start_btn, 140, 44);
683	  lv_obj_align(app->start_btn, LV_ALIGN_TOP_MID, 0, 90);
684	  lv_obj_set_style_bg_color(app->start_btn, lv_color_hex(0x1e88e5), 0);
685	  lv_obj_set_style_border_width(app->start_btn, 0, 0);
686	  lv_obj_add_event_cb(app->start_btn, start_btn_event_cb, LV_EVENT_CLICKED,
687	                      NULL);
688	
689	  lv_obj_t *btn_label = lv_label_create(app->start_btn);
690	  lv_label_set_text(btn_label, "Start");
691	  lv_obj_set_style_text_font(btn_label, font, 0);
692	  lv_obj_set_style_text_color(btn_label, lv_color_white(), 0);
693	  lv_obj_center(btn_label);
694	
695	  /* STT (what you said) label. */
696	  lv_obj_t *stt_caption = lv_label_create(scr);
697	  lv_label_set_text(stt_caption, "You:");
698	  lv_obj_set_style_text_font(stt_caption, font, 0);
699	  lv_obj_align(stt_caption, LV_ALIGN_TOP_LEFT, 30, 150);
700	
701	  app->stt_label = lv_label_create(scr);
702	  lv_label_set_text(app->stt_label, "-");
703	  lv_obj_set_style_text_font(app->stt_label, cjk_font, 0);
704	  lv_label_set_long_mode(app->stt_label, LV_LABEL_LONG_WRAP);
705	  lv_obj_set_width(app->stt_label, 300);
706	  lv_obj_align(app->stt_label, LV_ALIGN_TOP_LEFT, 30, 180);
707	
708	  /* TTS (reply) label. */
709	  lv_obj_t *tts_caption = lv_label_create(scr);
710	  lv_label_set_text(tts_caption, "Xiaozhi:");
711	  lv_obj_set_style_text_font(tts_caption, font, 0);
712	  lv_obj_align(tts_caption, LV_ALIGN_TOP_LEFT, 30, 250);
713	
714	  app->tts_label = lv_label_create(scr);
715	  lv_label_set_text(app->tts_label, "-");
716	  lv_obj_set_style_text_font(app->tts_label, cjk_font, 0);
717	  lv_label_set_long_mode(app->tts_label, LV_LABEL_LONG_WRAP);
718	  lv_obj_set_width(app->tts_label, 300);
719	  lv_obj_align(app->tts_label, LV_ALIGN_TOP_LEFT, 30, 280);
720	}
721	
722	/* Refresh the LVGL screen from the shared app state. */
723	static void ui_refresh(struct xiaozhi_app_s *app)
724	{
725	  if (app->status_label != NULL)
726	    {
727	      lv_label_set_text(app->status_label, g_state_names[app->state]);
728	    }
729	
730	  if (app->stt_label != NULL)
731	    {
732	      lv_label_set_text(app->stt_label,
733	                        app->stt_text[0] ? app->stt_text : "-");
734	    }
735	
736	  if (app->tts_label != NULL)
737	    {
738	      lv_label_set_text(app->tts_label,
739	                        app->tts_text[0] ? app->tts_text : "-");
740	    }
741	}
742	
743	/* Timer callback to refresh UI periodically */
744	static void ui_refresh_timer_cb(lv_timer_t *timer)
745	{
746	  LV_UNUSED(timer);
747	  ui_refresh(&g_app);
748	}
