750	/****************************************************************************
751	 * Public Functions
752	 ****************************************************************************/
753	
754	void xiaozhi_voice_start(void)
755	{
756	  LV_LOG_USER("==================xiaozhi_voice_start==================");
757	
758	  /* 隐藏applist */
759	  applist_hide_page();
760	
761	  /* 如果已经初始化过，直接显示 */
762	  if (g_app.status_label != NULL)
763	    {
764	      /* 显示所有UI元素 */
765	      lv_obj_clear_flag(g_app.status_label, LV_OBJ_FLAG_HIDDEN);
766	      lv_obj_clear_flag(g_app.start_btn, LV_OBJ_FLAG_HIDDEN);
767	      lv_obj_clear_flag(g_app.stt_label, LV_OBJ_FLAG_HIDDEN);
768	      lv_obj_clear_flag(g_app.tts_label, LV_OBJ_FLAG_HIDDEN);
769	      return;
770	    }
771	
772	  /* 初始化应用状态 */
773	  memset(&g_app, 0, sizeof(g_app));
774	  g_app.state = XZ_STATE_BOOT;
775	
776	  /* 初始化字体管理器（加载中文字体） */
777	  font_manager_init();
778	
779	  /* 创建UI */
780	  ui_create(&g_app);
781	
782	  /* 启动UI刷新定时器，每100ms刷新一次 */
783	  if (ui_refresh_timer == NULL)
784	    {
785	      ui_refresh_timer = lv_timer_create(ui_refresh_timer_cb, 100, NULL);
786	    }
787	}
788	
789	void xiaozhi_voice_delete(void)
790	{
791	  /* 停止UI刷新定时器 */
792	  if (ui_refresh_timer != NULL)
793	    {
794	      lv_timer_delete(ui_refresh_timer);
795	      ui_refresh_timer = NULL;
796	    }
797	
798	  if (g_app.status_label != NULL)
799	    {
800	      lv_obj_add_flag(g_app.status_label, LV_OBJ_FLAG_HIDDEN);
801	      lv_obj_add_flag(g_app.start_btn, LV_OBJ_FLAG_HIDDEN);
802	      lv_obj_add_flag(g_app.stt_label, LV_OBJ_FLAG_HIDDEN);
803	      lv_obj_add_flag(g_app.tts_label, LV_OBJ_FLAG_HIDDEN);
804	    }
805	}
