           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);

  /* Init audio subsystem (creates Opus encoder). */
  app->audio = xiaozhi_audio_init();
  if (app->audio == NULL)
    {
      printf("[xiaozhi] audio init failed\n");
      app->state = XZ_STATE_ERROR;
      return NULL;
    }

  /* Step 1: OTA. */
  app->state = XZ_STATE_OTA;
  printf("[xiaozhi] step 1: OTA\n");
  ret = xiaozhi_ota_fetch(mac, &ota);
  if (ret != 0)
    {
      printf("[xiaozhi] OTA failed: %d\n", ret);
      app->state = XZ_STATE_ERROR;
      return NULL;
    }

  /* Step 2: wss connect (TLS + ws upgrade). */
  app->state = XZ_STATE_CONNECT;
  printf("[xiaozhi] step 2: wss connect\n");
  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
                           client_id);
  if (ret != 0)
    {
      printf("[xiaozhi] ws connect failed: %d\n", ret);
      app->state = XZ_STATE_ERROR;
      return NULL;
    }

  app->ws_connected = true;

  /* Step 3: send the hello handshake, then wait for the server's hello
   * response which carries the session_id. The server times out (~10s)
   * if it never receives a hello, so we must send ours first.
   */
  printf("[xiaozhi] step 3: send hello + wait hello response\n");
  {
    cJSON *hello = cJSON_CreateObject();
    cJSON_AddStringToObject(hello, "type", "hello");
    cJSON_AddNumberToObject(hello, "version", 3);
    cJSON_AddStringToObject(hello, "transport", "websocket");

    cJSON *ap = cJSON_CreateObject();
    cJSON_AddStringToObject(ap, "format", "opus");
    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
    cJSON_AddNumberToObject(ap, "channels", 1);
    cJSON_AddNumberToObject(ap, "frame_duration", 60);
    cJSON_AddItemToObject(hello, "audio_params", ap);

    char *hello_str = cJSON_PrintUnformatted(hello);
    printf("[xiaozhi] >>> hello json: %s\n", hello_str ? hello_str : "null");
    if (hello_str)
      {
        free(hello_str);
      }
    ret = send_json(app, hello);
    cJSON_Delete(hello);
    if (ret != 0)
      {
        printf("[xiaozhi] hello send failed: %d\n", ret);
        app->state = XZ_STATE_ERROR;
        goto out;
      }
  }

  /* Receive the server hello response to get session_id. stop_on_hello
   * returns immediately once we have it, so we don't block waiting for
   * audio the server won't send before listen:start.
   */
  recv_loop(app, 5000, true);
  if (app->session_id[0] == '\0')
    {
      printf("[xiaozhi] no session_id, abort\n");
      app->state = XZ_STATE_ERROR;
      goto out;
    }

  /* Step 4: listen start + capture + listen stop. */
  app->state = XZ_STATE_LISTENING;
  printf("[xiaozhi] step 4: listen start + capture, session_id=%s\n",
         app->session_id);
  {
    cJSON *listen = cJSON_CreateObject();
    cJSON_AddStringToObject(listen, "session_id", app->session_id);
    cJSON_AddStringToObject(listen, "type", "listen");
    cJSON_AddStringToObject(listen, "state", "start");
    cJSON_AddStringToObject(listen, "mode", "manual");
    char *json_str = cJSON_PrintUnformatted(listen);
    printf("[xiaozhi] >>> listen start json: %s\n", json_str ? json_str : "null");
    if (json_str)
      {
        free(json_str);
      }
    send_json(app, listen);
    cJSON_Delete(listen);
  }

  ret = xiaozhi_audio_start_capture(app->audio);
  if (ret != 0)
    {
      printf("[xiaozhi] capture start failed: %d\n", ret);
      app->state = XZ_STATE_ERROR;
      goto out;
    }

  {
    struct uplink_ctx_s uc;
    uc.app = app;
    uc.seconds = XZ_DIALOG_SECONDS;
    uplink_worker(&uc);
  }

  xiaozhi_audio_stop_capture(app->audio);

  /* listen stop. */
  {
    cJSON *stop = cJSON_CreateObject();
    cJSON_AddStringToObject(stop, "session_id", app->session_id);
    cJSON_AddStringToObject(stop, "type", "listen");
    cJSON_AddStringToObject(stop, "state", "stop");
    char *json_str = cJSON_PrintUnformatted(stop);
    printf("[xiaozhi] >>> listen stop json: %s\n", json_str ? json_str : "null");
    if (json_str)
      {
        free(json_str);
      }
    send_json(app, stop);
    cJSON_Delete(stop);
  }

  /* Step 5: receive stt + tts + playback (up to 20s). */
  app->state = XZ_STATE_THINKING;
  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
  recv_loop(app, 20000, false);

out:
  if (app->tts_playing)
    {
      xiaozhi_audio_stop_playback(app->audio);
    }

  xiaozhi_audio_deinit(app->audio);
  xiaozhi_ws_close(&app->ws);

  app->state = XZ_STATE_DONE;
  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
         app->got_stt ? "yes" : "no", app->tts_sentences);

  /* Reset state so user can start a new conversation. */
  app->dialog_started = false;
  app->ws_connected = false;
  app->got_stt = false;
  app->tts_playing = false;
  app->tts_sentences = 0;
  memset(app->session_id, 0, sizeof(app->session_id));
  memset(app->stt_text, 0, sizeof(app->stt_text));
  memset(app->tts_text, 0, sizeof(app->tts_text));

  /* Show the start button for the next conversation. */
  if (app->start_btn != NULL)
    {
      lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
    }

  return NULL;
}

