/* Async helper: run on the main LVGL thread to show the start button.
 * Called via lv_async_call() from dialog_thread so we never touch LVGL
 * from a non-LVGL thread (LVGL is NOT thread-safe).
 */
static void async_show_start_btn(void *arg)
{
  struct xiaozhi_app_s *app = arg;
  if (app->start_btn != NULL)
    {
      lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
    }
}

