226	         target_frames, uc->seconds);
227	
228	  
229	  printf("[xiaozhi] app->ws_connected %d\n", app->ws_connected);
230	
231	  while (frames < target_frames && app->ws_connected)
232	    {
233	      printf("[xiaozhi] in while show, frames=%d, target=%d, connected=%d\n",
234	             frames, target_frames, app->ws_connected);
235	      ssize_t n = xiaozhi_audio_read_opus(app->audio, frame, sizeof(frame));
236	      printf("[xiaozhi] read_opus returned: %zd\n", n);
237	      if (n < 0)
238	        {
239	          printf("[xiaozhi] uplink read err: %zd\n", n);
240	          break;
241	        }
242	
243	      if (n > 0)
244	        {
245	          /* Debug: hex dump first Opus frames for format verification. */
246	          if (frames < 3)
247	            {
248	              printf("[xiaozhi] opus frame[%d] len=%zd\n", frames, n);
249	              for (ssize_t i = 0; i < n && i < 32; i++)
250	                {
251	                  printf("%02x ", frame[i]);
252	                }
253	              printf("\n");
254	            }
255	
256	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
257	          if (ret != 0)
258	            {
259	              printf("[xiaozhi] uplink send err: %d\n", ret);
260	              break;
261	            }
262	
263	          frames++;
264	        }
265	    }
266	
267	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
268	  return NULL;
269	}
