431	/* Async helper: run on the main LVGL thread to show the start button.
432	 * Called via lv_async_call() from dialog_thread so we never touch LVGL
433	 * from a non-LVGL thread (LVGL is NOT thread-safe).
434	 */
435	static void async_show_start_btn(void *arg)
436	{
437	  struct xiaozhi_app_s *app = arg;
438	  if (app->start_btn != NULL)
439	    {
440	      lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
441	    }
442	}
