444	/* Dialog thread: runs the full OTA -> dialog flow off the main (UI) thread.
445	 */
446	static void *dialog_thread(void *arg)
447	{
448	  struct xiaozhi_app_s *app = arg;
449	  struct xiaozhi_ota_config_s ota;
450	  const char *mac = XIAOZHI_MAC_DEFAULT;
451	  char client_id[40];
452	  int ret;
453	
454	  snprintf(client_id, sizeof(client_id),
455	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
456	
457	  /* Init audio subsystem (creates Opus encoder). */
458	  app->audio = xiaozhi_audio_init();
459	  if (app->audio == NULL)
460	    {
461	      printf("[xiaozhi] audio init failed\n");
462	      app->state = XZ_STATE_ERROR;
463	      return NULL;
464	    }
465	
466	  /* Step 1: OTA. */
467	  app->state = XZ_STATE_OTA;
468	  printf("[xiaozhi] step 1: OTA\n");
469	  ret = xiaozhi_ota_fetch(mac, &ota);
470	  if (ret != 0)
471	    {
472	      printf("[xiaozhi] OTA failed: %d\n", ret);
473	      app->state = XZ_STATE_ERROR;
474	      return NULL;
475	    }
476	
477	  /* Step 2: wss connect (TLS + ws upgrade). */
478	  app->state = XZ_STATE_CONNECT;
479	  printf("[xiaozhi] step 2: wss connect\n");
480	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
481	                           client_id);
482	  if (ret != 0)
483	    {
484	      printf("[xiaozhi] ws connect failed: %d\n", ret);
485	      app->state = XZ_STATE_ERROR;
486	      return NULL;
487	    }
488	
489	  app->ws_connected = true;
490	
491	  /* Step 3: send the hello handshake, then wait for the server's hello
492	   * response which carries the session_id. The server times out (~10s)
493	   * if it never receives a hello, so we must send ours first.
494	   */
495	  printf("[xiaozhi] step 3: send hello + wait hello response\n");
496	  {
497	    cJSON *hello = cJSON_CreateObject();
498	    cJSON_AddStringToObject(hello, "type", "hello");
499	    cJSON_AddNumberToObject(hello, "version", 3);
500	    cJSON_AddStringToObject(hello, "transport", "websocket");
501	
502	    cJSON *ap = cJSON_CreateObject();
503	    cJSON_AddStringToObject(ap, "format", "opus");
504	    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
505	    cJSON_AddNumberToObject(ap, "channels", 1);
506	    cJSON_AddNumberToObject(ap, "frame_duration", 60);
507	    cJSON_AddItemToObject(hello, "audio_params", ap);
508	
509	    char *hello_str = cJSON_PrintUnformatted(hello);
510	    printf("[xiaozhi] >>> hello json: %s\n", hello_str ? hello_str : "null");
511	    if (hello_str)
512	      {
513	        free(hello_str);
514	      }
515	    ret = send_json(app, hello);
516	    cJSON_Delete(hello);
517	    if (ret != 0)
518	      {
519	        printf("[xiaozhi] hello send failed: %d\n", ret);
520	        app->state = XZ_STATE_ERROR;
521	        goto out;
522	      }
523	  }
524	
525	  /* Receive the server hello response to get session_id. stop_on_hello
526	   * returns immediately once we have it, so we don't block waiting for
527	   * audio the server won't send before listen:start.
528	   */
529	  recv_loop(app, 5000, true);
530	  if (app->session_id[0] == '\0')
531	    {
532	      printf("[xiaozhi] no session_id, abort\n");
533	      app->state = XZ_STATE_ERROR;
534	      goto out;
535	    }
536	
537	  /* Step 4: listen start + capture + listen stop. */
538	  app->state = XZ_STATE_LISTENING;
539	  printf("[xiaozhi] step 4: listen start + capture, session_id=%s\n",
540	         app->session_id);
541	  {
542	    cJSON *listen = cJSON_CreateObject();
543	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
544	    cJSON_AddStringToObject(listen, "type", "listen");
545	    cJSON_AddStringToObject(listen, "state", "start");
546	    cJSON_AddStringToObject(listen, "mode", "manual");
547	    char *json_str = cJSON_PrintUnformatted(listen);
548	    printf("[xiaozhi] >>> listen start json: %s\n", json_str ? json_str : "null");
549	    if (json_str)
550	      {
551	        free(json_str);
552	      }
553	    send_json(app, listen);
554	    cJSON_Delete(listen);
555	  }
556	
557	  ret = xiaozhi_audio_start_capture(app->audio);
558	  if (ret != 0)
559	    {
560	      printf("[xiaozhi] capture start failed: %d\n", ret);
561	      app->state = XZ_STATE_ERROR;
562	      goto out;
563	    }
564	
565	  {
566	    struct uplink_ctx_s uc;
567	    uc.app = app;
568	    uc.seconds = XZ_DIALOG_SECONDS;
569	    uplink_worker(&uc);
570	  }
571	
572	  xiaozhi_audio_stop_capture(app->audio);
573	
574	  /* listen stop. */
575	  {
576	    cJSON *stop = cJSON_CreateObject();
577	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
578	    cJSON_AddStringToObject(stop, "type", "listen");
579	    cJSON_AddStringToObject(stop, "state", "stop");
580	    char *json_str = cJSON_PrintUnformatted(stop);
581	    printf("[xiaozhi] >>> listen stop json: %s\n", json_str ? json_str : "null");
582	    if (json_str)
583	      {
584	        free(json_str);
585	      }
586	    send_json(app, stop);
587	    cJSON_Delete(stop);
588	  }
589	
590	  /* Step 5: receive stt + tts + playback (up to 20s). */
591	  app->state = XZ_STATE_THINKING;
592	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
593	  recv_loop(app, 20000, false);
594	
595	out:
596	  if (app->tts_playing)
597	    {
598	      xiaozhi_audio_stop_playback(app->audio);
599	    }
600	
601	  xiaozhi_audio_deinit(app->audio);
602	  xiaozhi_ws_close(&app->ws);
603	
604	  app->state = XZ_STATE_DONE;
605	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
606	         app->got_stt ? "yes" : "no", app->tts_sentences);
607	
608	  /* Reset state so user can start a new conversation. */
609	  app->dialog_started = false;
610	  app->ws_connected = false;
611	  app->got_stt = false;
612	  app->tts_playing = false;
613	  app->tts_sentences = 0;
614	  memset(app->session_id, 0, sizeof(app->session_id));
615	  memset(app->stt_text, 0, sizeof(app->stt_text));
616	  memset(app->tts_text, 0, sizeof(app->tts_text));
617	
618	  /* Show the start button for the next conversation.
619	   * MUST use lv_async_call() — LVGL is not thread-safe and we are
620	   * running in a pthread, not the LVGL main thread.
621	   */
622	  lv_async_call(async_show_start_btn, app);
623	
624	  return NULL;
625	}
