627	/* Start button click handler: kicks off the dialog thread on demand.
628	 * The user taps this after WiFi is up, so OTA can reach the server.
629	 */
630	static void start_btn_event_cb(lv_event_t *e)
631	{
632	  struct xiaozhi_app_s *app = &g_app;
633	  LV_UNUSED(e);
634	
635	  if (app->dialog_started)
636	    {
637	      return;   /* already running */
638	    }
639	
640	  app->dialog_started = true;
641	  app->state = XZ_STATE_OTA;
642	
643	  /* Hide the start button once the dialog is launched. */
644	  if (app->start_btn != NULL)
645	    {
646	      lv_obj_add_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
647	    }
648	
649	  pthread_attr_t attr;
650	  pthread_attr_init(&attr);
651	  pthread_attr_setstacksize(&attr, 65536);
652	
653	  int ret = pthread_create(NULL, &attr, dialog_thread, app);
654	  pthread_attr_destroy(&attr);
655	
656	  if (ret != 0)
657	    {
658	      printf("[xiaozhi] dialog thread create failed: %d\n", ret);
659	      app->state = XZ_STATE_ERROR;
660	      app->dialog_started = false;
661	      if (app->start_btn != NULL)
662	        {
663	          lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
664	        }
665	    }
666	}
