668	/* Build the LVGL main screen. */
669	static void ui_create(struct xiaozhi_app_s *app)
670	{
671	  lv_obj_t *scr = get_watch_scr();
672	  lv_obj_set_style_bg_color(scr, lv_color_white(), 0);
673	
674	  /* Use the default font for English UI elements. */
675	  const lv_font_t *font = lv_font_default();
676	
677	  /* Use Chinese-capable font for STT/TTS text display. */
678	  const lv_font_t *cjk_font = font_manager_get_font(FONT_SMALL);
679	
680	  /* Title. */
681	  lv_obj_t *title = lv_label_create(scr);
682	  lv_label_set_text(title, "Xiaozhi Voice");
683	  lv_obj_set_style_text_font(title, font, 0);
684	  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 20);
685	
686	  /* Status line. */
687	  app->status_label = lv_label_create(scr);
688	  lv_label_set_text(app->status_label, g_state_names[app->state]);
689	  lv_obj_set_style_text_font(app->status_label, font, 0);
690	  lv_obj_set_style_text_color(app->status_label, lv_color_hex(0x1e88e5), 0);
691	  lv_obj_align(app->status_label, LV_ALIGN_TOP_MID, 0, 60);
692	
693	  /* Start button: user taps this (after WiFi is up) to begin the dialog. */
694	  app->start_btn = lv_button_create(scr);
695	  lv_obj_set_size(app->start_btn, 140, 44);
696	  lv_obj_align(app->start_btn, LV_ALIGN_TOP_MID, 0, 90);
697	  lv_obj_set_style_bg_color(app->start_btn, lv_color_hex(0x1e88e5), 0);
698	  lv_obj_set_style_border_width(app->start_btn, 0, 0);
699	  lv_obj_add_event_cb(app->start_btn, start_btn_event_cb, LV_EVENT_CLICKED,
700	                      NULL);
701	
702	  lv_obj_t *btn_label = lv_label_create(app->start_btn);
703	  lv_label_set_text(btn_label, "Start");
704	  lv_obj_set_style_text_font(btn_label, font, 0);
705	  lv_obj_set_style_text_color(btn_label, lv_color_white(), 0);
706	  lv_obj_center(btn_label);
707	
708	  /* STT (what you said) label. */
709	  lv_obj_t *stt_caption = lv_label_create(scr);
710	  lv_label_set_text(stt_caption, "You:");
711	  lv_obj_set_style_text_font(stt_caption, font, 0);
712	  lv_obj_align(stt_caption, LV_ALIGN_TOP_LEFT, 30, 150);
713	
714	  app->stt_label = lv_label_create(scr);
715	  lv_label_set_text(app->stt_label, "-");
716	  lv_obj_set_style_text_font(app->stt_label, cjk_font, 0);
717	  lv_label_set_long_mode(app->stt_label, LV_LABEL_LONG_WRAP);
718	  lv_obj_set_width(app->stt_label, 300);
719	  lv_obj_align(app->stt_label, LV_ALIGN_TOP_LEFT, 30, 180);
720	
721	  /* TTS (reply) label. */
722	  lv_obj_t *tts_caption = lv_label_create(scr);
723	  lv_label_set_text(tts_caption, "Xiaozhi:");
724	  lv_obj_set_style_text_font(tts_caption, font, 0);
725	  lv_obj_align(tts_caption, LV_ALIGN_TOP_LEFT, 30, 250);
726	
727	  app->tts_label = lv_label_create(scr);
728	  lv_label_set_text(app->tts_label, "-");
729	  lv_obj_set_style_text_font(app->tts_label, cjk_font, 0);
730	  lv_label_set_long_mode(app->tts_label, LV_LABEL_LONG_WRAP);
731	  lv_obj_set_width(app->tts_label, 300);
732	  lv_obj_align(app->tts_label, LV_ALIGN_TOP_LEFT, 30, 280);
733	}
