767	void xiaozhi_voice_start(void)
768	{
769	  LV_LOG_USER("==================xiaozhi_voice_start==================");
770	
771	  /* 隐藏applist */
772	  applist_hide_page();
773	
774	  /* 如果已经初始化过，直接显示 */
775	  if (g_app.status_label != NULL)
776	    {
777	      /* 显示所有UI元素 */
778	      lv_obj_clear_flag(g_app.status_label, LV_OBJ_FLAG_HIDDEN);
779	      lv_obj_clear_flag(g_app.start_btn, LV_OBJ_FLAG_HIDDEN);
780	      lv_obj_clear_flag(g_app.stt_label, LV_OBJ_FLAG_HIDDEN);
781	      lv_obj_clear_flag(g_app.tts_label, LV_OBJ_FLAG_HIDDEN);
782	      return;
783	    }
784	
785	  /* 初始化应用状态 */
786	  memset(&g_app, 0, sizeof(g_app));
787	  g_app.state = XZ_STATE_BOOT;
788	
789	  /* 初始化字体管理器（加载中文字体） */
790	  font_manager_init();
791	
792	  /* 创建UI */
793	  ui_create(&g_app);
794	
795	  /* 启动UI刷新定时器，每100ms刷新一次 */
796	  if (ui_refresh_timer == NULL)
797	    {
798	      ui_refresh_timer = lv_timer_create(ui_refresh_timer_cb, 100, NULL);
799	    }
800	}
