802	void xiaozhi_voice_delete(void)
803	{
804	  /* 停止UI刷新定时器 */
805	  if (ui_refresh_timer != NULL)
806	    {
807	      lv_timer_delete(ui_refresh_timer);
808	      ui_refresh_timer = NULL;
809	    }
810	
